inline TXST::TXST(const TXST &o)
      : ID(o.ID),
        NATIVE_ID(o.NATIVE_ID),
        SITE_NAME(o.SITE_NAME),
        STATION_IDENTITY(o.STATION_IDENTITY),
        LICENSEE(o.LICENSEE),
        LICENSE_ID(o.LICENSE_ID),
        SERVICE(o.SERVICE),
        STATUS(o.STATUS),
        COUNTRY_CODE(o.COUNTRY_CODE),
        ADMIN_AREA(o.ADMIN_AREA),
        LATITUDE(o.LATITUDE),
        LONGITUDE(o.LONGITUDE),
        POSITION_AUTHORITY(o.POSITION_AUTHORITY),
        POSITION_UNCERTAINTY_M(o.POSITION_UNCERTAINTY_M),
        POSITION_DISPUTED(o.POSITION_DISPUTED),
        GROUND_ELEVATION_AMSL_M(o.GROUND_ELEVATION_AMSL_M),
        STRUCTURE_HEIGHT_AGL_M(o.STRUCTURE_HEIGHT_AGL_M),
        STRUCTURE(o.STRUCTURE),
        STRUCTURE_COUNT(o.STRUCTURE_COUNT),
        FIRST_OBSERVED(o.FIRST_OBSERVED),
        LAST_OBSERVED(o.LAST_OBSERVED),
        CONSENSUS((o.CONSENSUS) ? new TXSConsensusT(*o.CONSENSUS) : nullptr) {
  PRIOR_POSITIONS.reserve(o.PRIOR_POSITIONS.size());
  for (const auto &PRIOR_POSITIONS_ : o.PRIOR_POSITIONS) { PRIOR_POSITIONS.emplace_back((PRIOR_POSITIONS_) ? new TXSPriorPositionT(*PRIOR_POSITIONS_) : nullptr); }
  EMISSIONS.reserve(o.EMISSIONS.size());
  for (const auto &EMISSIONS_ : o.EMISSIONS) { EMISSIONS.emplace_back((EMISSIONS_) ? new TXSEmissionT(*EMISSIONS_) : nullptr); }
  SOURCES.reserve(o.SOURCES.size());
  for (const auto &SOURCES_ : o.SOURCES) { SOURCES.emplace_back((SOURCES_) ? new TXSProvenanceT(*SOURCES_) : nullptr); }
}

